import sys

def solve():
    data = sys.stdin.read().split()
    if not data:
        return
    n = int(data[0])
    k = int(data[1])
    s = list(data[2])

    i = 0
    while k > 0 and i < n - 1:
        if s[i] == '4' and s[i+1] == '7':
            if i % 2 == 0:
                s[i] = '4'
                s[i+1] = '4'
                if i + 2 < n and s[i+2] == '7':
                    i += 1
                    continue
                else:
                    i += 2
            else:
                s[i] = '7'
                s[i+1] = '7'
                i -= 1
            k -= 1
            if k == 0:
                break
        else:
            i += 1

    print(''.join(s))

if __name__ == "__main__":
    solve()
